@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name = "cretas.platform.factory-assembly.enabled", havingValue = "true", matchIfMissing = false)
@Component public class EquipmentCalibrationDraftProposer implements CapabilityDraftProposer { private static final String WHY="蓝图没有设备、周期、方法、容差、责任人和过程关联的完整事实"; private static <E extends Enum<E>> List<Option> opts(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(e->new Option(e.name(),e.name())).toList();} private static <E extends Enum<E>> String ec(Class<E> c){return Arrays.stream(c.getEnumConstants()).map(Enum::name).collect(java.util.stream.Collectors.joining("、"))+" 之一";} private static List<RequiredInput> fields(){return List.of(RequiredInput.integer("equipmentId","设备",WHY,"设备 ID",1,Integer.MAX_VALUE),RequiredInput.text("equipmentSnapshotDigest","设备摘要",WHY,"SHA-256",64),RequiredInput.oneOf("planType","计划类型",WHY,ec(PlanType.class),opts(PlanType.class)),RequiredInput.oneOf("frequencyKind","频率类型",WHY,ec(FrequencyKind.class),opts(FrequencyKind.class)),RequiredInput.integer("frequencyValue","频率数值",WHY,"正整数",1,100000),RequiredInput.oneOf("duePolicy","到期策略",WHY,ec(DuePolicy.class),opts(DuePolicy.class)),RequiredInput.text("method","方法",WHY,"1–500 字",500),RequiredInput.decimal("toleranceValue","容差",WHY,"非负",java.math.BigDecimal.ZERO,java.math.BigDecimal.valueOf(100000)).allowNull(),RequiredInput.text("toleranceUnit","容差单位",WHY,"最长 32 位",32).allowNull(),RequiredInput.text("responsibleRole","责任角色",WHY,"最长 128 位",128),RequiredInput.text("requiredEvidence","要求证据",WHY,"最长 500 位",500),RequiredInput.text("verificationMethod","验证方法",WHY,"最长 500 位",500),RequiredInput.integer("estimatedDurationMinutes","预计分钟",WHY,"1–100000",1,100000),RequiredInput.text("changeReason","变更原因",WHY,"1–500 字",500),RequiredInput.list("processRefs","过程关联",WHY,"至少 1 条","过程",1,20,List.of(RequiredInput.text("processId","过程",WHY,"最长 128 位",128),RequiredInput.text("processDraftId","过程草稿",WHY,"最长 128 位",128),RequiredInput.text("processSnapshotDigest","过程摘要",WHY,"SHA-256",64))));} public String capabilityId(){return EquipmentCalibrationPlanDraftCommand.CAPABILITY_ID;} public Proposed propose(Source s){var req=new DraftRequest(s.factoryId(),s.blueprint().getId(),s.blueprint().getVersion(),s.sourceDigest(),List.of(),null,null,0);return Proposed.single(capabilityId(),"设备校准计划",req,List.of(RequiredInput.list("plans","校准计划",WHY,"至少 1 条，最多 200 条","计划",1,200,fields())),List.of());}}

